# Search existing saved programs for nested rectangular-ring implementations.
paths=list(prog_dir.glob('task-*.py'))
hits=[]
for q in paths:
    txt=q.read_text()
    if ('range(' in txt and ('5' in txt) and ('2' in txt) and ('bbox' in txt or 'border' in txt or 'depth' in txt or 'ring' in txt)):
        hits.append((q.name,txt[:1200]))
print('candidate files',len(hits))
for name,txt in hits[:5]: print('\n',name,'\n',txt)
